from fastapi import FastAPI
from fastapi.concurrency import run_in_threadpool

app = FastAPI()

def build_report(year: int) -> list[dict[str, int]]:
    return [{"year": year, "rows": 128}]

@app.get("/report")
async def report():
    # Blocking SDK calls run in a worker thread, not on the event loop
    data = await run_in_threadpool(build_report, 2026)
    return {"rows": len(data)}

from datetime import datetime, timedelta, timezone
import jwt
from fastapi import Depends, FastAPI, HTTPException, status
from fastapi.security import OAuth2PasswordBearer

SECRET = "change-this-in-production"
ALGORITHM = "HS256"
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")

app = FastAPI()

def create_access_token(subject: str) -> str:
    payload = {
        "sub": subject,
        "exp": datetime.now(timezone.utc) + timedelta(minutes=30),
    }
    return jwt.encode(payload, SECRET, algorithm=ALGORITHM)

def current_user(token: str = Depends(oauth2_scheme)) -> str:
    try:
        claims = jwt.decode(token, SECRET, algorithms=[ALGORITHM])
    except jwt.InvalidTokenError:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid token",
            headers={"WWW-Authenticate": "Bearer"},
        )
    return claims["sub"]

@app.get("/me")
def me(user: str = Depends(current_user)):
    return {"user": user}

